$canManage=app_has_permission('wholesale.manage',$user);
$canInventory=app_has_permission('inventory.manage',$user);
$orderId=trim((string)($_GET['id']??''));
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Fulfillment</title>
<style>
:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6d716b;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--good:#157347;--warn:#9a6200;--bad:#a62a24;--shadow:0 14px 38px rgba(24,25,21,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.top{min-height:64px;padding:10px 20px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:0;z-index:30}.brand{display:flex;align-items:center;gap:11px}.logo{width:38px;height:38px;border-radius:11px;background:var(--dark);display:grid;place-items:center;color:#fff;font-weight:900}.brand small{display:block;color:var(--muted);font-size:9px}.nav{display:flex;gap:7px;flex-wrap:wrap}.btn{min-height:36px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);padding:8px 11px;font-size:9px;font-weight:900;text-decoration:none;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.dark{background:var(--dark);border-color:var(--dark);color:#fff}.btn.good{background:var(--good);border-color:var(--good);color:#fff}.btn.danger{color:var(--bad)}.btn:disabled{opacity:.4;cursor:not-allowed}.shell{max-width:1500px;margin:auto;padding:22px}.hero{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:15px}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.12em}.hero h1{margin:5px 0 6px;font-size:36px;letter-spacing:-.05em}.hero p{margin:0;color:var(--muted);font-size:11px;line-height:1.5;max-width:850px}.layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:14px}.panel{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 4px 18px rgba(20,20,18,.03)}.sidebar{padding:12px;position:sticky;top:86px;max-height:calc(100vh - 105px);overflow:auto}.field{width:100%;min-height:39px;border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:#fff}.order-list{display:grid;gap:7px;margin-top:10px}.order-card{border:1px solid var(--line);border-radius:11px;padding:11px;background:#fff;cursor:pointer}.order-card.active{border-color:var(--accent);box-shadow:0 0 0 2px rgba(217,74,43,.08)}.order-card strong{font-size:11px}.order-card p{margin:3px 0 0;color:var(--muted);font-size:9px}.tag{display:inline-block;margin-top:7px;padding:4px 7px;border-radius:999px;background:#f1f0ec;font-size:7px;font-weight:900;text-transform:uppercase}.main{display:grid;gap:12px}.section{padding:16px}.section h2{margin:0 0 5px;font-size:16px}.section>p{margin:0 0 12px;color:var(--muted);font-size:10px;line-height:1.45}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.metric{padding:12px;border:1px solid var(--line);border-radius:12px}.metric small{display:block;color:var(--muted);font-size:7px;font-weight:900;text-transform:uppercase}.metric strong{display:block;margin-top:5px;font-size:21px}.bar{height:6px;background:#ecebe7;border-radius:999px;overflow:hidden;margin-top:7px}.bar span{display:block;height:100%;background:currentColor}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.wide{grid-column:1/-1}.label{display:block;margin:0 0 4px;color:#575c56;font-size:7px;font-weight:900;text-transform:uppercase}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:11px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:9px;border-bottom:1px solid #ecece8;text-align:left;font-size:9px}th{background:#f7f6f2;font-size:7px;text-transform:uppercase;color:#5f635d}tr:last-child td{border-bottom:0}.qty{width:88px;min-height:31px;border:1px solid var(--line);border-radius:7px;padding:5px}.batches{display:grid;gap:8px}.batch{border:1px solid var(--line);border-radius:12px;padding:12px}.batch-head{display:flex;align-items:start;justify-content:space-between;gap:10px}.batch h3{margin:0;font-size:12px}.batch p{margin:4px 0 0;color:var(--muted);font-size:9px}.batch-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.note{padding:10px;border-radius:9px;background:#f6f5f2;color:var(--muted);font-size:9px;line-height:1.45}.note.warn{background:#fff5df;color:#73520d}.note.bad{background:#fff0ef;color:#8d2923}.note.good{background:#edf8f2;color:#116641}.empty{padding:24px;border:1px dashed #c9c9c2;border-radius:10px;text-align:center;color:var(--muted);font-size:10px}.status{position:fixed;right:18px;bottom:18px;z-index:70;background:#171b1a;color:#fff;padding:10px 13px;border-radius:10px;font-size:10px;box-shadow:var(--shadow)}.hidden{display:none}.actions{display:flex;justify-content:flex-end;gap:7px;margin-top:11px}.mono{font-variant-numeric:tabular-nums}@media(max-width:980px){.layout{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.shell{padding:13px}.hero{align-items:flex-start;flex-direction:column}.hero h1{font-size:30px}.grid,.metrics{grid-template-columns:1fr}.wide{grid-column:auto}}
</style></head><body>
<header class="top"><div class="brand"><div class="logo">G</div><div><strong>Wholesale Fulfillment</strong><small>Allocation · partial fulfillment · inventory consumption</small></div></div><nav class="nav"><a class="btn" href="wholesale-purchasing.php">Planner</a><a class="btn" href="wholesale-accounts.php">Accounts</a><a class="btn" href="wholesale-demand.php">Demand</a><a class="btn" href="operations.php">Operations</a></nav></header>
<main class="shell"><section class="hero"><div><p class="eyebrow">Wholesale W3</p><h1>Inventory allocation + fulfillment</h1><p>Allocate confirmed Wholesale orders into one or more pickup, delivery, or shipment batches. Final delivery consumes canonical restaurant inventory exactly once and releases the corresponding remaining ingredient commitment.</p></div><button class="btn" id="refresh">Refresh</button></section>
<div class="layout"><aside class="panel sidebar"><input class="field" id="search" placeholder="Search account or order…"><div class="order-list" id="orders"><div class="empty">Loading orders…</div></div></aside><section class="main" id="main"><div class="panel section"><div class="empty">Select a Wholesale order to manage fulfillment.</div></div></section></div></main><div class="status hidden" id="status"></div>
<script>window.WF={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,id:<?=json_encode($orderId)?>,canManage:<?=$canManage?'true':'false'?>,canInventory:<?=$canInventory?'true':'false'?>};</script>
<script>
(()=>{const cfg=window.WF,by=id=>document.getElementById(id);let orders=[],detail=null,active=cfg.id||'';const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const num=v=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:2});const dt=v=>v?String(v).replace(' ','T').slice(0,16):'';function toast(t){const e=by('status');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),2300)}async function get(url){const r=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function post(body){const r=await fetch('api/wholesale-fulfillment.php',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-Token':cfg.csrf},body:JSON.stringify({...body,csrf_token:cfg.csrf})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function load(){const d=await get('api/wholesale-fulfillment.php?action=list');orders=d.orders||[];renderOrders();if(active)await openOrder(active)}function renderOrders(){const q=by('search').value.trim().toLowerCase(),rows=orders.filter(o=>!q||[o.business_name,o.order_number,o.status].join(' ').toLowerCase().includes(q));by('orders').innerHTML=rows.length?rows.map(o=>`<article class="order-card ${active===o.public_id?'active':''}" data-id="${esc(o.public_id)}"><strong>${esc(o.order_number)} · ${esc(o.business_name)}</strong><p>${esc(o.fulfillment_type||'Fulfillment TBD')}${o.promised_window_start?' · '+esc(o.promised_window_start):''}</p><span class="tag">${esc(o.status)} · ${Number(o.fulfillment_count||0)} batch${Number(o.fulfillment_count||0)===1?'':'es'}</span></article>`).join(''):'<div class="empty">No matching Wholesale orders.</div>';document.querySelectorAll('.order-card').forEach(el=>el.onclick=()=>openOrder(el.dataset.id))}async function openOrder(id){active=id;history.replaceState({},'',`wholesale-fulfillment.php?id=${encodeURIComponent(id)}`);renderOrders();const d=await get('api/wholesale-fulfillment.php?action=detail&id='+encodeURIComponent(id));detail=d.detail;renderDetail()}function renderDetail(){const d=detail,o=d.order,p=d.progress,a=d.availability;const locations=d.locations||[];const canAllocate=cfg.canManage&&!['requested','delivered','cancelled'].includes(o.status);by('main').innerHTML=`<section class="panel section"><p class="eyebrow">${esc(o.businessName)}</p><h2>${esc(o.number)} · ${esc(o.status)}</h2><div class="metrics"><div class="metric"><small>Allocated</small><strong>${p.allocationPercent}%</strong><div class="bar" style="color:var(--accent)"><span style="width:${Math.min(100,p.allocationPercent)}%"></span></div></div><div class="metric"><small>Delivered</small><strong>${p.deliveryPercent}%</strong><div class="bar" style="color:var(--good)"><span style="width:${Math.min(100,p.deliveryPercent)}%"></span></div></div><div class="metric"><small>Fulfillment batches</small><strong>${d.batches.length}</strong><span class="tag">${p.partialDelivered?'partial delivered':p.allDelivered?'complete':'open'}</span></div><div class="metric"><small>ATP shortages</small><strong>${a.shortages}</strong><span class="tag">${a.shortages?'attention':'clear'}</span></div></div></section>${planSection(o,locations)}${linesSection(p.lines,canAllocate)}${availabilitySection(a)}${batchesSection(d.batches)}`;bindDetail(canAllocate)}function planSection(o,locations){return `<section class="panel section"><h2>Order fulfillment plan</h2><p>Set the account location and requested/promised service windows. Batch windows default from this plan.</p><div class="grid"><div><label class="label">Method</label><select class="field" id="fulfillmentType"><option value="pickup" ${o.fulfillmentType==='pickup'?'selected':''}>Pickup</option><option value="local_delivery" ${o.fulfillmentType==='local_delivery'?'selected':''}>Local delivery</option><option value="shipment" ${o.fulfillmentType==='shipment'?'selected':''}>Shipment</option></select></div><div class="wide"><label class="label">Account location</label><select class="field" id="locationId"><option value="">No specific location</option>${locations.map(l=>`<option value="${esc(l.public_id)}" ${String(o.locationId||'')===String(l.id)||String(o.locationId||'')===String(l.public_id)?'selected':''}>${esc(l.name)} · ${esc([l.address_line1,l.city,l.state_region].filter(Boolean).join(', '))}</option>`).join('')}</select></div><div><label class="label">Requested start</label><input class="field" id="requestedWindowStart" type="datetime-local" value="${esc(dt(o.requestedWindowStart))}"></div><div><label class="label">Requested end</label><input class="field" id="requestedWindowEnd" type="datetime-local" value="${esc(dt(o.requestedWindowEnd))}"></div><div><label class="label">Promised start</label><input class="field" id="promisedWindowStart" type="datetime-local" value="${esc(dt(o.promisedWindowStart))}"></div><div><label class="label">Promised end</label><input class="field" id="promisedWindowEnd" type="datetime-local" value="${esc(dt(o.promisedWindowEnd))}"></div></div>${cfg.canManage&&!['delivered','cancelled'].includes(o.status)?'<div class="actions"><button class="btn primary" id="savePlan">Save fulfillment plan</button></div>':''}</section>`}function linesSection(lines,canAllocate){return `<section class="panel section"><h2>Order allocation</h2><p>Create a batch from any remaining unallocated line quantity. Multiple batches support partial deliveries without changing the canonical order line.</p><div class="table-wrap"><table><thead><tr><th>Line</th><th>Item</th><th>Ordered</th><th>Allocated</th><th>Delivered</th><th>Remaining</th>${canAllocate?'<th>New batch qty</th>':''}</tr></thead><tbody>${lines.map(l=>`<tr><td>${l.lineNumber}</td><td><strong>${esc(l.name)}</strong><br><small>${esc(l.sku||'')} · ${esc(l.unit||'')}</small></td><td>${num(l.ordered)}</td><td>${num(l.allocated)}</td><td>${num(l.delivered)}</td><td>${num(l.remainingToAllocate)}</td>${canAllocate?`<td><input class="qty" data-line="${l.lineNumber}" type="number" min="0" max="${l.remainingToAllocate}" step=".01" value=""></td>`:''}</tr>`).join('')}</tbody></table></div>${canAllocate?`<div class="grid" style="margin-top:10px"><div><label class="label">Batch method</label><select class="field" id="batchType"><option value="pickup">Pickup</option><option value="local_delivery">Local delivery</option><option value="shipment">Shipment</option></select></div><div><label class="label">Batch location</label><select class="field" id="batchLocation"><option value="">Use order/default location</option>${(detail.locations||[]).map(l=>`<option value="${esc(l.public_id)}">${esc(l.name)}</option>`).join('')}</select></div><div class="wide"><label class="label">Batch notes</label><input class="field" id="batchNotes" placeholder="Route, pickup contact, special handling…"></div></div><div class="actions"><button class="btn dark" id="createBatch">Create fulfillment batch</button></div>`:''}</section>`}function availabilitySection(a){return `<section class="panel section"><h2>Ingredient availability</h2><p>Remaining committed demand versus current canonical on-hand inventory. Delivery is blocked rather than silently driving stock negative.</p>${a.issues.length?`<div class="note warn" style="margin-bottom:9px">${esc(a.issues.map(x=>`Line ${x.line||'—'}: ${x.message}`).join(' · '))}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Inventory item</th><th>On hand</th><th>Remaining order demand</th><th>Shortage</th></tr></thead><tbody>${a.items.length?a.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong></td><td>${num(i.onHand)} ${esc(i.unit||'')}</td><td>${num(i.remainingDemand)} ${esc(i.unit||'')}</td><td>${i.shortage>0?`<span style="color:var(--bad);font-weight:900">${num(i.shortage)}</span>`:'0'}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">No mapped remaining ingredient demand.</div></td></tr>'}</tbody></table></div></section>`}function batchesSection(batches){return `<section class="panel section"><h2>Fulfillment batches</h2><p>Each delivered batch records exact inventory use. Retrying an already delivered batch is idempotent and does not consume inventory twice.</p><div class="batches">${batches.length?batches.map(batchCard).join(''):'<div class="empty">No fulfillment batches yet.</div>'}</div></section>`}function batchCard(b){const can=cfg.canManage,items=b.items.map(i=>`Line ${i.lineNumber}: ${num(i.quantity)} ${esc(i.unit||'')} ${esc(i.name)}`).join(' · '),cons=b.consumptions.length?`<div class="note good" style="margin-top:8px">Inventory consumed: ${b.consumptions.map(c=>`${num(c.quantity)} ${esc(c.unit)} ${esc(c.inventory_name)}`).join(' · ')}</div>`:'';let actions='';if(can&&b.status==='draft')actions=`<button class="btn primary" data-act="ready" data-id="${b.id}">Mark ready</button><button class="btn danger" data-act="cancel" data-id="${b.id}">Cancel</button>`;if(can&&b.status==='ready')actions=`<button class="btn dark" data-act="dispatch" data-id="${b.id}">Dispatch</button>${cfg.canInventory?`<button class="btn good" data-act="deliver" data-id="${b.id}">Deliver now</button>`:''}<button class="btn danger" data-act="cancel" data-id="${b.id}">Cancel</button>`;if(can&&b.status==='dispatched'&&cfg.canInventory)actions=`<button class="btn good" data-act="deliver" data-id="${b.id}">Confirm delivered</button>`;return `<article class="batch"><div class="batch-head"><div><h3>${esc(b.number)} · ${esc(b.status)}</h3><p>${esc(b.fulfillmentType)}${b.promisedWindowStart?' · '+esc(b.promisedWindowStart):''}</p></div><span class="tag">${b.items.length} line${b.items.length===1?'':'s'}</span></div><div class="note" style="margin-top:8px">${items}</div>${cons}${actions?`<div class="batch-actions">${actions}</div>`:''}${!cfg.canInventory&&['ready','dispatched'].includes(b.status)?'<div class="note warn" style="margin-top:8px">Final delivery requires inventory.manage permission because it consumes physical inventory.</div>':''}</article>`}function bindDetail(canAllocate){if(by('savePlan'))by('savePlan').onclick=async()=>{try{const d=await post({action:'plan.save',orderId:active,fulfillmentType:by('fulfillmentType').value,locationId:by('locationId').value,requestedWindowStart:by('requestedWindowStart').value,requestedWindowEnd:by('requestedWindowEnd').value,promisedWindowStart:by('promisedWindowStart').value,promisedWindowEnd:by('promisedWindowEnd').value});detail=d.detail;renderDetail();toast(d.message)}catch(e){toast(e.message)}};if(canAllocate&&by('createBatch'))by('createBatch').onclick=async()=>{const items=[...document.querySelectorAll('[data-line]')].map(el=>({lineNumber:Number(el.dataset.line),quantity:Number(el.value||0)})).filter(x=>x.quantity>0);try{const d=await post({action:'batch.create',orderId:active,items,fulfillmentType:by('batchType').value,locationId:by('batchLocation').value,notes:by('batchNotes').value});detail=d.detail;renderDetail();await refreshList();toast(d.message)}catch(e){toast(e.message)}};document.querySelectorAll('[data-act]').forEach(btn=>btn.onclick=async()=>{const action=btn.dataset.act,id=btn.dataset.id;if(action==='deliver'&&!confirm('Confirm delivery? This will consume the batch ingredient quantities from canonical inventory.'))return;try{const d=await post({action:`batch.${action}`,batchId:id});detail=d.detail;renderDetail();await refreshList();toast(d.message)}catch(e){toast(e.message)}})}async function refreshList(){const d=await get('api/wholesale-fulfillment.php?action=list');orders=d.orders||[];renderOrders()}by('search').oninput=renderOrders;by('refresh').onclick=()=>load().catch(e=>toast(e.message));load().catch(e=>toast(e.message))})();
</script></body></html>
